evidence.sql:

          WITH level1 AS (
            select distinct website_event.session_id, website_event.created_at
            from website_event


            where website_event.website_id = {{websiteId::uuid}}
              and website_event.created_at between {{startDate}} and {{endDate}}
              and url_path = {{0}}


          )

          , level2 AS (
            select distinct we.session_id, we.created_at
            from level1 l
            join website_event we
                on l.session_id = we.session_id
            where we.website_id = {{websiteId::uuid}}
                and we.created_at between l.created_at and l.created_at  + interval '60 minute'
                and we.url_path = {{1}}
                and we.created_at <= {{endDate}}

          )
          , level3 AS (
            select distinct we.session_id, we.created_at
            from level2 l
            join website_event we
                on l.session_id = we.session_id
            where we.website_id = {{websiteId::uuid}}
                and we.created_at between l.created_at and l.created_at  + interval '60 minute'
                and we.url_path = {{2}}
                and we.created_at <= {{endDate}}

          )

select 1 as level, count(distinct(session_id)) as count from level1
union select 2 as level, count(distinct(session_id)) as count from level2
union select 3 as level, count(distinct(session_id)) as count from level3
    ORDER BY level;

